 static void execute(Fixture f)throws Throwable{var b=f.base().first().base().base();var pc=b.caster();var payload=SourceTargetNegativeLifePlan.packet(27,777);NativeLightAction.dispatch(pc,payload);}
 static List<byte[]> packets(SourceNpcHpOutputPlan.MemorySocket socket){
  var result=new ArrayList<byte[]>();var cipher=new Protocol.CipherState(12345);byte[] bytes=socket.bytes.toByteArray();int offset=0;
  while(offset<bytes.length){check(offset+2<=bytes.length,"complete encrypted frame header");int length=(bytes[offset]&255)|((bytes[offset+1]&255)<<8);check(length>=3&&offset+length<=bytes.length,"complete native encrypted frame");result.add(cipher.decrypt(Arrays.copyOfRange(bytes,offset+2,offset+length)));offset+=length;frames++;}return result;
 }
 static long count(List<byte[]> packets,byte[] expected){return packets.stream().filter(p->Arrays.equals(p,expected)).count();}
