 static void queryWait(String mode)throws Throwable{
  var f=fixture();var b=f.base().first().base().base();var pet=f.base().first().pet();
  put(b.caster(),"sourceCounterMagicBypassSkills",Set.of());
  var entered=new CountDownLatch(1);var resume=new CountDownLatch(1);var error=new AtomicReference<Throwable>();
  f.queryHook().set(()->{entered.countDown();try{if(!resume.await(5,TimeUnit.SECONDS))throw new AssertionError("query release missing");}catch(InterruptedException e){throw new AssertionError(e);}});
  var worker=new Thread(()->{try{execute(f);}catch(Throwable t){error.set(t);}},"actual-weapon-nonempty-source-query-"+mode);
  try{
   worker.start();check(entered.await(3,TimeUnit.SECONDS),"actual original Source query reached controlled wait");
   check(Arrays.stream(worker.getStackTrace()).anyMatch(x->x.getMethodName().equals("nativeSourceWeaponFirstPrepare")),"wait occurs within complete original Source NPC query path");
   SourceTargetNegativeReservePlan.mutate(f.base(),mode);resume.countDown();worker.join(3000);
   check(!worker.isAlive()&&error.get()==null,"full native material attempt terminates after stale first input "+mode+" error="+error.get());
   check((int)CombatAccess.field(b.caster(),"playerMp")==100&&((RuntimeInventory)CombatAccess.field(b.caster(),"inventory")).countCatalog(40318)==3&&pet.weaponBreakStacks()==0,"stale role/status/actor/lifetime rejected before original material/MP/stack "+mode);
   check(f.sockets().values().stream().allMatch(s->s.bytes.size()==0),"stale Source result emits no original frame "+mode);
   SourceTargetNegativeReservePlan.noInit(f.base(),mode);queryWaits++;
  }finally{resume.countDown();worker.join(3000);check(!worker.isAlive(),"query worker is terminal before fixture cleanup");cleanup(f);}
 }
